import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Typography, Button, CircularProgress } from "@mui/material";
import { supabase } from "../supabase";

const VerifyPage = () => {
  const [status, setStatus] = useState("checking");
  const navigate = useNavigate();

  useEffect(() => {
    const checkVerification = async () => {
      try {
        const fullURL = window.location.href;

        // ✅ Make sure it contains the access_token/code
        if (!fullURL.includes("#")) {
          console.error("No access token or hash in URL");
          setStatus("failed");
          return;
        }

        const { error: exchangeError } = await supabase.auth.exchangeCodeForSession(fullURL);

        if (exchangeError) {
          console.error("Error exchanging code:", exchangeError.message);
          setStatus("failed");
          return;
        }

        // Optional short wait to ensure session is saved
        await new Promise((res) => setTimeout(res, 1000));

        const { data: userData, error: userError } = await supabase.auth.getUser();
        if (userError || !userData?.user) {
          console.error("User fetch error:", userError?.message);
          setStatus("failed");
          return;
        }

        const confirmed = userData.user.confirmed_at !== null;
        setStatus(confirmed ? "verified" : "pending");
      } catch (err) {
        console.error("Unexpected error:", err);
        setStatus("failed");
      }
    };

    checkVerification();
  }, []);

  return (
    <Box sx={{ textAlign: "center", mt: 10 }}>
      {status === "checking" && (
        <>
          <CircularProgress />
          <Typography mt={2}>Checking verification status...</Typography>
        </>
      )}

      {status === "verified" && (
        <>
          <Typography variant="h5" mb={2} color="green">
            ✅ Your email has been verified!
          </Typography>
          <Button
            variant="contained"
            onClick={() => navigate("/signin")}
            sx={{ backgroundColor: "#8E2839" }}
          >
            Go to Sign In
          </Button>
        </>
      )}

      {status === "pending" && (
        <>
          <Typography color="orange" variant="body1" mb={2}>
            ⚠️ Email not yet verified.
          </Typography>
          <Typography variant="body2" mb={2}>
            Please check your inbox and click the confirmation link again.
          </Typography>
          <Button
            variant="outlined"
            onClick={() => window.location.reload()}
            sx={{ color: "#8E2839", borderColor: "#8E2839" }}
          >
            Recheck Status
          </Button>
        </>
      )}

      {status === "failed" && (
        <>
          <Typography color="red" variant="body1" mb={2}>
            ❌ Unable to verify your account.
          </Typography>
          <Typography variant="body2" mb={2}>
            Make sure you're using the verification link from your email, in the same browser where you signed up.
          </Typography>
          <Button
            variant="contained"
            sx={{ backgroundColor: "#8E2839" }}
            onClick={() => navigate("/signin")}
          >
            Back to Sign In
          </Button>
        </>
      )}
    </Box>
  );
};

export default VerifyPage;
